//! A target's register pressure sets, from its `pressure.sets` (generated by
//! `tools/pressure_sets.py` from the pin's `X86GenRegisterInfoTargetDesc.inc`):
//! `set <index> <name> <limit> <largest class>` and `class <name> <weight>
//! <registers> <sets> <visible registers>`, sets comma separated and `-` for
//! none.

/// A pressure set: its raw limit, before the reserved registers are taken off.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct PressureSet {
    pub name: String,
    pub limit: u32,
    /// `getLargestRegClassForRegPressureSet`.
    pub largest: String,
}

/// A register class: the weight of one of its registers, and the pressure sets
/// it counts in (`getRegClassPressureSets`).
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct PressureClass {
    pub name: String,
    pub weight: u32,
    /// `getNumRegs()`, the registers the pin's class has on every x86 target.
    pub registers: u32,
    pub sets: Vec<usize>,
    /// The registers of the class this target describes.
    pub visible: Vec<String>,
}

#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct PressureSets {
    pub sets: Vec<PressureSet>,
    pub classes: Vec<PressureClass>,
}

pub fn parse(text: &str) -> Result<PressureSets, String> {
    let mut out = PressureSets::default();
    for (index, raw) in text.lines().enumerate() {
        let line = raw.split('#').next().unwrap_or("").trim();
        if line.is_empty() {
            continue;
        }
        let at = |what: &str| format!("pressure.sets:{}: {what}", index + 1);
        fn number<T: std::str::FromStr>(
            text: &str,
            what: &str,
            at: &impl Fn(&str) -> String,
        ) -> Result<T, String> {
            text.parse().map_err(|_| at(&format!("{what} `{text}`")))
        }
        let list = |text: &str| -> Vec<String> {
            if text == "-" { Vec::new() } else { text.split(',').map(str::to_owned).collect() }
        };
        match line.split_whitespace().collect::<Vec<_>>()[..] {
            ["set", number_of, name, limit, largest] => {
                if number::<usize>(number_of, "set", &at)? != out.sets.len() {
                    return Err(at("sets are numbered from 0 in order"));
                }
                out.sets.push(PressureSet {
                    name: name.to_owned(),
                    limit: number(limit, "limit", &at)?,
                    largest: largest.to_owned(),
                });
            }
            ["class", name, weight, registers, sets, visible] => out.classes.push(PressureClass {
                name: name.to_owned(),
                weight: number(weight, "weight", &at)?,
                registers: number(registers, "registers", &at)?,
                sets: list(sets).iter().map(|one| number(one, "set", &at)).collect::<Result<_, _>>()?,
                visible: list(visible),
            }),
            _ => return Err(at("a `set` or a `class` line")),
        }
    }
    Ok(out)
}

impl PressureSets {
    pub fn class(
        &self,
        name: &str,
    ) -> Option<&PressureClass> {
        self.classes.iter().find(|class| class.name == name)
    }

    /// `RegisterClassInfo::computePSetLimit` (RegisterClassInfo.cpp#L263): the
    /// raw limit less the weight of the registers of the set's largest class
    /// that cannot be allocated. A register the target does not describe
    /// counts as reserved, as the pin's x86 reserves the registers of the
    /// modes it is not in. `allocatable` tells whether a described register
    /// may be.
    pub fn limit(
        &self,
        set: usize,
        allocatable: impl Fn(&str) -> bool,
    ) -> u32 {
        let PressureSet { limit, largest, .. } = &self.sets[set];
        let class = self.class(largest).expect("the largest class of a set is described");
        let free = class.visible.iter().filter(|one| allocatable(one)).count() as u32;
        if free == 0 {
            return *limit;
        }
        let reserved_weight = class.weight * (class.registers - free);
        if reserved_weight >= *limit { *limit } else { limit - reserved_weight }
    }

    /// The class a value confined to `allowed` has: the smallest one that holds
    /// all of them (the pin knows the exact class from selection; this is the
    /// one its registers pick out), the first of the file on a tie.
    pub fn class_holding(
        &self,
        allowed: &[&str],
    ) -> Option<&PressureClass> {
        self.classes
            .iter()
            .filter(|class| allowed.iter().all(|one| class.visible.iter().any(|seen| seen == one)))
            .min_by_key(|class| class.visible.len())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = "\
set 0 SMALL 4 BIG
set 1 WIDE 10 BIG
class BIG 2 6 0,1 a,b,c
class PAIR 2 2 1 a,b
";

    #[test]
    fn the_limit_takes_the_reserved_weight_off() {
        let sets = parse(SAMPLE).expect("parses");
        // BIG has 6 registers in the pin, 3 described and 2 allocatable: 4
        // reserved at weight 2.
        assert_eq!(sets.limit(1, |name| name != "c"), 2);
        // Reserved weight 8 >= limit 4: the raw limit stands.
        assert_eq!(sets.limit(0, |name| name != "c"), 4);
        // Nothing allocatable: the raw limit.
        assert_eq!(sets.limit(1, |_| false), 10);
    }

    #[test]
    fn a_value_confined_to_two_registers_has_the_smaller_class() {
        let sets = parse(SAMPLE).expect("parses");
        assert_eq!(sets.class_holding(&["a", "b"]).map(|class| class.name.as_str()), Some("PAIR"));
        assert_eq!(sets.class_holding(&["a", "c"]).map(|class| class.name.as_str()), Some("BIG"));
    }
}
